import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Payment Gateways & Processing","description":"","frontmatter":{},"headers":[],"relativePath":"admin/payment-gateways.md","filePath":"admin/payment-gateways.md"}'),r={name:"admin/payment-gateways.md"};function s(i,e,c,l,d,u){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="payment-gateways-processing" tabindex="-1">Payment Gateways &amp; Processing <a class="header-anchor" href="#payment-gateways-processing" aria-label="Permalink to &quot;Payment Gateways &amp; Processing&quot;">​</a></h1><p>FOSSBilling includes an extensible payment processing subsystem supporting both synchronous card checkouts, digital wallets, QRIS, and offline bank transfers.</p><hr><h2 id="💳-supported-payment-gateways" tabindex="-1">💳 Supported Payment Gateways <a class="header-anchor" href="#💳-supported-payment-gateways" aria-label="Permalink to &quot;💳 Supported Payment Gateways&quot;">​</a></h2><h3 id="_1-stripe-stripe" tabindex="-1">1. Stripe (<code>stripe</code>) <a class="header-anchor" href="#_1-stripe-stripe" aria-label="Permalink to &quot;1. Stripe (`stripe`)&quot;">​</a></h3><ul><li><strong>Payment Methods:</strong> Credit/Debit Cards, Apple Pay, Google Pay, SEPA Direct Debit.</li><li><strong>Configuration:</strong> <code>Secret Key</code> (<code>sk_live_...</code>), <code>Publishable Key</code> (<code>pk_live_...</code>), <code>Webhook Secret</code> (<code>whsec_...</code>).</li><li><strong>Webhook Endpoint:</strong> <code>POST /api/v1/guest/payment/webhook/stripe</code></li></ul><h3 id="_2-paypal-express-checkout-paypal" tabindex="-1">2. PayPal Express Checkout (<code>paypal</code>) <a class="header-anchor" href="#_2-paypal-express-checkout-paypal" aria-label="Permalink to &quot;2. PayPal Express Checkout (`paypal`)&quot;">​</a></h3><ul><li><strong>Payment Methods:</strong> PayPal balance, connected bank accounts, Pay in 4.</li><li><strong>Configuration:</strong> <code>Client ID</code>, <code>Client Secret</code>, <code>Sandbox Mode</code> (true/false).</li><li><strong>Webhook Endpoint:</strong> <code>POST /api/v1/guest/payment/webhook/paypal</code></li></ul><h3 id="_3-midtrans-midtrans" tabindex="-1">3. Midtrans (<code>midtrans</code>) <a class="header-anchor" href="#_3-midtrans-midtrans" aria-label="Permalink to &quot;3. Midtrans (`midtrans`)&quot;">​</a></h3><ul><li><strong>Payment Methods:</strong> QRIS (GoPay, OVO, Dana, LinkAja), Virtual Accounts (BCA, Mandiri, BNI, BRI), Credit Cards.</li><li><strong>Configuration:</strong> <code>Server Key</code>, <code>Client Key</code>, <code>Production Mode</code> (true/false).</li><li><strong>Notification Endpoint:</strong> <code>POST /api/v1/guest/payment/webhook/midtrans</code></li></ul><h3 id="_4-bank-transfer-custom-manual-gateway-bank-transfer" tabindex="-1">4. Bank Transfer / Custom Manual Gateway (<code>bank_transfer</code>) <a class="header-anchor" href="#_4-bank-transfer-custom-manual-gateway-bank-transfer" aria-label="Permalink to &quot;4. Bank Transfer / Custom Manual Gateway (`bank_transfer`)&quot;">​</a></h3><ul><li><strong>Payment Methods:</strong> Manual bank transfer / wire transfer.</li><li><strong>Configuration:</strong> Bank Name, Account Number, Account Holder, Instructions.</li><li><strong>Workflow:</strong> Generates pending transaction; staff approve with 1-click upon receipt confirmation.</li></ul><hr><h2 id="💱-multi-currency-exchange-rates" tabindex="-1">💱 Multi-Currency &amp; Exchange Rates <a class="header-anchor" href="#💱-multi-currency-exchange-rates" aria-label="Permalink to &quot;💱 Multi-Currency &amp; Exchange Rates&quot;">​</a></h2><ol><li>Navigate to <strong>Currencies</strong> (<code>/currencies</code>) in Admin Portal.</li><li>Define a <strong>Default Currency</strong> (e.g. <code>USD</code> or <code>IDR</code>).</li><li>Add secondary currencies with automated or custom exchange rates.</li><li>Prices in invoices and storefronts are dynamically converted and formatted according to client currency.</li></ol>',15)])])}const y=a(r,[["render",s]]);export{m as __pageData,y as default};
